 "content": "def transform(grid):
    h, w = len(grid), len(grid[0])
    row_cuts = [r for r, row in enumerate(grid) if len(set(row)) == 1]
    col_cuts = [c for c in range(w) if len({grid[r][c] for r in range(h)}) == 1]

    def spans(n, cuts):
        result, start = [], 0
        for cut in cuts:
            if start < cut:
                result.append((start, cut))
            start = cut + 1
        if start < n:
            result.append((start, n))
        return result

    rows, cols = spans(h, row_cuts), spans(w, col_cuts)
    output = []
    for r0, r1 in rows:
        out_row = []
        for c0, c1 in cols:
            vals = [grid[r][c] for r in range(r0, r1) for c in range(c0, c1)]
            freq = {v: vals.count(v) for v in set(vals)}
            background = max(freq, key=freq.get)
            marks = len(vals) - freq[background]
            out_row.append(1 if marks == 2 else background)
        output.append(out_row)
    return output
